<!DOCTYPE html>
<html lang="en" dir="rtl">
<head>
    <meta charset="UTF-8" />
    <meta http-equiv="X-UA-Compatible" content="IE=edge" />
    <meta
        name="viewport"
        content="width=device-width, initial-scale=1.0, shrink-to-fit=no"
    />
    <meta name="description" content="فاتورة الطلب" />
    <title>فاتورة الطلب</title>
    <style>

        /* body */
        body {
            font-family: "din-light";
            margin: 0;
        }

        .logo {
        }

        .logo-desc {
            font-size: 18px;
            margin-top: 12px;
        }

        .table-title {
            color: #000;
            font-size: 20px;
            font-family: "din-bold";
            margin-bottom: 12px;
        }

        .info-row {
            justify-content: space-between;
            align-items: center;
            font-size: 14px;
            color: #555;
            border-top: 1px solid #ddd;
            padding: 20px;
            margin-top: 45px;
        }

        .info-row span {
            white-space: nowrap;
            font-size: 16px;
        }

        .invoice-header {
            border-top: 15px solid #000084;
            overflow: hidden;
        }
        .invoice {
            overflow: hidden;
        }
        .tableSection table,
        .details-table {
            border-collapse: collapse;
        }

        table th,
        table td {
            padding: 20px;
            width: auto;
            text-align: center;
        }

        table th {
            background-color: #f2f2f2;
            color: #263b8a;
        }

        table tr {
        }

        .highlight-row td {
            background-color: #f8f8f8;
            font-weight: bold;
        }

        .highlight-row td:nth-of-type(2),
        .highlight-row td:last-child {
            font-size: 18px;
        }

        .details-table td {
            text-align: start;
            padding: 8px 0;
            border-bottom: 1px solid #ddd;
        }

        .details-table .total-row {
            font-weight: bold;
            border-top: 3px solid #000084;
        }

        .details-table .total-row td {
            color: #000084;
            font-family: "din-bold";
            font-size: 18px;
        }

        .details-table .final-total {
            color: #00008b;
            font-size: 18px;
        }

        .hold-invoice-header {
            margin-top: 20px;
        }

        @media (max-width: 992px) {
            .table-title {
                font-size: 18px;
            }

            table th,
            table td {
                font-size: 14px;
                padding: 15px;
            }

            .details-table td {
                font-size: 14px;
                padding: 5px 0;
            }

            .info-row span {
                font-size: 14px;
            }

            .details-table .total-row td {
                font-size: 15px;
            }

            .highlight-row td:nth-of-type(2),
            .highlight-row td:last-child {
                font-size: 14px;
            }
        }

        /* .invoice-header img:not(.logo img) {
          width: 100%;
        } */

        .tableSection {
            margin-bottom: 30px;
        }

        @media (max-width: 768px) {
            .tableSection table,
            .details-table {
                display: block;
                overflow-x: auto;
                overflow-y: hidden;
                -webkit-overflow-scrolling: touch;
            }
        }
        .mb-4 {
            margin-bottom: 1.5rem !important;
        }
        .container,
        .container-fluid,
        .container-lg,
        .container-md,
        .container-sm,
        .container-xl,
        .container-xxl {
            --bs-gutter-x: 1.5rem;
            --bs-gutter-y: 0;
            width: 100%;
            margin-right: auto;
            margin-left: auto;
        }
        @media (min-width: 576px) {
            .container,
            .container-sm {
                max-width: 540px;
            }
        }
        @media (min-width: 768px) {
            .container,
            .container-md,
            .container-sm {
                max-width: 720px;
            }
        }
        @media (min-width: 992px) {
            .container,
            .container-lg,
            .container-md,
            .container-sm {
                max-width: 960px;
            }
        }
        @media (min-width: 1200px) {
            .container,
            .container-lg,
            .container-md,
            .container-sm,
            .container-xl {
                max-width: 1140px;
            }
        }
        @media (min-width: 1400px) {
            .container,
            .container-lg,
            .container-md,
            .container-sm,
            .container-xl,
            .container-xxl {
                max-width: 1320px;
            }
        }
        .row {
            --bs-gutter-x: 1.5rem;
            --bs-gutter-y: 0;
            margin-top: calc(-1 * var(--bs-gutter-y));

            overflow: hidden;
            display: inline;
        }
        .row > * {
            width: 100%;
            max-width: 100%;
            padding-right: calc(-0.5 * var(--bs-gutter-x));
            padding-left: calc(-0.5 * var(--bs-gutter-x));
            margin-top: var(--bs-gutter-y);
        }
        .col-1 {
            float: right;
            width: 8.33333333%;
        }
        .col-2 {
            float: right;
            width: 16.66666667%;
        }
        .col-3 {
            float: right;
            width: 25%;
        }
        .col-4 {
            float: right;
            width: 33.33333333%;
        }
        .col-5 {
            float: right;
            width: 41.66666667%;
        }
        .col-6 {
            float: right;
            width: 50%;
        }
        .col-7 {
            float: right;
            width: 58.33333333%;
        }
        .col-8 {
            float: right;
            width: 66.66666667%;
        }
        .col-9 {
            float: right;
            width: 75%;
        }
        .col-10 {
            float: right;
            width: 83.33333333%;
        }
        .col-11 {
            float: right;
            width: 91.66666667%;
        }
        .col-12 {
            float: right;
            width: 100%;
        }
        .text-start {
            text-align: left !important;
        }
        .text-end {
            text-align: right !important;
        }
        .text-center {
            text-align: center !important;
        }
        .right {
            float: right;
        }
        .left {
            float: left;
        }
        .block {
            display: block;
        }
    </style>
</head>
<body>
<main id="bodyWrap">
    <div class="container">
        <section class="invoice-header">
            <div class="hold-invoice-header">
                <div class="row">
                    <div class="col-md-2 col-3">
                        <div class="Qcode right text-center">
                            <p class="code-tit">فاتورة ضريبية مبسطة</p>
                            <img
                                src="data:image/png;base64,"
                                alt="Code"
                                width="200"
                            />
                            <p class="code-num">45244072</p>
                        </div>
                    </div>
                    <div class="col-md-8 col-6">
                        <div class="logo text-center">
                            <img
                                src="data:image/png;base64,"
                                alt="Logo"
                            />
                        </div>
                        <p class="logo-desc text-center">شركة الدعم الذكي</p>
                    </div>
                    <div class="col-md-2 col-3">
                        <div class="Qcode left">
                            <img
                                src="data:image/png;base64,"
                                alt="QR Code"
                                width="150"
                            />
                        </div>
                    </div>
                </div>
            </div>
        </section>

        <!-- Invoice Details -->
        <div class="invoice">
            <div class="row mb-4">
                <div class="col-12">
                    <div class="row">
                        <div class="col-6">
                            <div class="hold-details">
                                <p><strong>رقم الفاتورة:</strong> 45244072</p>
                                <p>
                                    <strong>تاريخ إصدار الفاتورة:</strong> 2024-12-15 00:59
                                    GMT+03:00
                                </p>
                                <p><strong>حالة الحجز:</strong> جديد</p>
                            </div>
                        </div>
                        <div class="col-6"></div>
                    </div>
                </div>
                <div class="col-12">
                    <div class="row">
                        <div class="col-6">
                            <div class="hold-details">
                                <p><strong>اسم العميل:</strong> بدر علي</p>
                                <p><strong>رقم الهاتف:</strong> +966599990445</p>
                                <p><strong>البريد الإلكتروني:</strong></p>
                            </div>
                        </div>
                        <div class="col-6">
                            <div class="hold-details">
                                <p><strong>طريقة الدفع:</strong> Apple Pay</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- Services Table -->
        <section class="tableSection">
            <div class="table-title">الخدمات</div>
            <table width="100%">
                <thead>
                <tr>
                    <th>#</th>
                    <th>اسم الخدمة</th>
                    <th>السعر (قبل الضريبة)</th>
                    <th>الضريبة</th>
                    <th>السعر (بعد الضريبة)</th>
                    <th>الإجمالي</th>
                </tr>
                </thead>
                <tbody>
                <tr>
                    <td>1</td>
                    <td class="product-name">
                        <p class="product-title">
                            لي ماء وحدائق مطور - 1/2 بوصة - أخضر بخط رمادي - 25 متر
                        </p>
                    </td>
                    <td>SAR 86.96</td>
                    <td>SAR 13.04</td>
                    <td>SAR 100.00</td>
                    <td>SAR 100.00</td>
                </tr>
                <tr>
                    <td>1</td>
                    <td class="product-name">
                        <p class="product-title">
                            لي ماء وحدائق مطور - 1/2 بوصة - أخضر بخط رمادي - 25 متر
                        </p>
                    </td>
                    <td>SAR 86.96</td>
                    <td>SAR 13.04</td>
                    <td>SAR 100.00</td>
                    <td>SAR 100.00</td>
                </tr>
                </tbody>
                <tfoot>
                <tr class="highlight-row">
                    <td colspan="3"></td>
                    <td colspan="2">إجمالي الخدمات</td>
                    <td colspan="1">SAR 100.00</td>
                </tr>
                </tfoot>
            </table>
        </section>

        <!-- Product Table -->
        <section class="tableSection">
            <div class="table-title">المنتجات</div>
            <table width="100%">
                <thead>
                <tr>
                    <th>#</th>
                    <th>اسم المنتج</th>
                    <th>السعر (قبل الضريبة)</th>
                    <th>الضريبة</th>
                    <th>السعر (بعد الضريبة)</th>
                    <th>الكمية</th>
                    <th>الإجمالي</th>
                </tr>
                </thead>
                <tbody>
                <tr>
                    <td>1</td>
                    <td class="product-name">
                        <p class="product-title">
                            لي ماء وحدائق مطور - 1/2 بوصة - أخضر بخط رمادي - 25 متر
                        </p>
                    </td>

                    <td>SAR 86.96</td>
                    <td>SAR 13.04</td>
                    <td>SAR 100.00</td>
                    <td>1</td>
                    <td>SAR 100.00</td>
                </tr>
                </tbody>
                <tfoot>
                <tr class="highlight-row">
                    <td colspan="4"></td>
                    <td colspan="2">إجمالي المنتجات</td>
                    <td colspan="1">SAR 100.00</td>
                </tr>
                </tfoot>
            </table>
        </section>

        <!-- Pricing Details -->
        <section class="priceDetails">
            <div class="table-title">تفاصيل التكلفة</div>
            <div class="row block">
                <table width="100%" class="details-table">
                    <tbody>
                    <tr>
                        <td>إجمالي تكلفة الخدمات</td>
                        <td>SAR 86.96</td>
                    </tr>
                    <tr>
                        <td>إجمالي تكلفة المنتجات</td>
                        <td>SAR 21.74</td>
                    </tr>
                    <tr>
                        <td>إجمالي التكلفة</td>
                        <td>SAR 108.70</td>
                    </tr>
                    <tr>
                        <td>كود الخصم (ws3)</td>
                        <td>SAR 108.70</td>
                    </tr>
                    <tr>
                        <td>رصيد النقاط</td>
                        <td>SAR 16.30</td>
                    </tr>
                    <tr>
                        <td>رسوم الحجز</td>
                        <td>SAR 125.00</td>
                    </tr>
                    <tr class="total-row">
                        <td>الإجمالي النهائي</td>
                        <td class="final-total">SAR 125.00</td>
                    </tr>
                    </tbody>
                </table>
            </div>
        </section>
        <footer>
            <div class="info-row">
                <div class="col-4 text-center">
              <span
              ><strong>عنوان المتجر:</strong> السعودية الرياض المناخ
                ينبع</span
              >
                </div>
                <div class="col-4 text-center">
                    <span><strong>الرقم الضريبي:</strong> 302006492000003</span>
                </div>
                <div class="col-4 text-center">
                    <span><strong>السجل التجاري:</strong> 1010090173</span>
                </div>
            </div>
        </footer>
    </div>
</main>
</body>
</html>
